def collect_text(x):
    if isinstance(x,dict):
        if x.get('role')=='user':
            c=x.get('content','')
            if isinstance(c,str): texts.append(c)
            elif isinstance(c,list):
                texts.extend(i.get('text','') for i in c if isinstance(i,dict) and i.get('type')=='text')
        for v in x.values():
            if isinstance(v,(dict,list)): collect_text(v)
    elif isinstance(x,list):
        for v in x: collect_text(v)
